CREATE TABLE sales.orders (id NUMBER PRIMARY KEY, customer_id NUMBER, status VARCHAR2(10), created DATE, amount NUMBER);
CREATE TABLE sales.customers (id NUMBER PRIMARY KEY, name VARCHAR2(100), region VARCHAR2(10));

SELECT c.name,
       (SELECT SUM(o.amount) FROM sales.orders o WHERE o.customer_id = c.id) AS total
  FROM sales.customers c;

SELECT DISTINCT o.status, COUNT(*) FROM sales.orders o WHERE o.status = 'NEW' GROUP BY o.status;

SELECT id FROM sales.orders WHERE status = 'A'
UNION
SELECT id FROM sales.orders WHERE status = 'B';

SELECT * FROM sales.orders o WHERE o.amount + 1 = 5;

UPDATE sales.orders SET status = 'X' WHERE customer_id = 7;
UPDATE sales.orders SET amount = 0 WHERE customer_id = 7;

BEGIN
  FOR r IN (SELECT id FROM sales.orders WHERE status = 'OLD') LOOP
    DELETE FROM sales.customers WHERE id = r.id;
  END LOOP;
END;
/

